
from abc import ABCMeta
from taf.ul.ettf.scheduler.base_listeners import SuiteListener
from taf.ul.ettf.scheduler.robot_policy_scheduler import Policy, PolicyScheduler
from taf.ul.ettf.utils.robot_handlers import RobotKeywordDecorator
from future.utils import with_metaclass


class Suite(object):
    pass


class Test(object):
    pass


class Any(object):
    pass


class RobotPolicyTrigger(with_metaclass(ABCMeta, SuiteListener, PolicyScheduler)):
    def __init__(self):
        super(RobotPolicyTrigger, self).__init__()
        self._policy = self._default_value()

    def _default_value(self):
        return Policy()

    def start_suite(self, suite, result):
        self._policy = self.get()
        self._run_callbacks(Suite, suite)
        self._run_callbacks(Any, suite)

    def start_test(self, test, result):
        self._run_callbacks(Test, test)
        self._run_callbacks(Any, test)

    def _run_callbacks(self, scope, context):
        for _callback in self._policy.get(scope, []):
            self._run_callback(_callback, context)

    @staticmethod
    def _run_callback(_callback, context):
        return RobotKeywordDecorator()(_callback)
